#ifndef RESULT_SCHEMA_H
#define RESULT_SCHEMA_H

#include <iostream>
#include <string>
#include <vector>
#include <memory>
#include <nlohmann/json.hpp>
#include <z6_base_json.h>

using json = nlohmann::json;



class Z6ResultJson : public Z6json {
private:
    std::string report_;
    bool report_valid_;
    std::vector<std::string> players_;
    bool players_valid_;

public:
    Z6ResultJson() : report_valid_(false), players_valid_(false) {}
    Z6ResultJson(const Z6ResultJson& other) : report_(other.report_), report_valid_(other.report_valid_), players_(other.players_), players_valid_(other.players_valid_) {}
    Z6ResultJson& operator=(const Z6ResultJson& other);

    static bool validate(const std::string& json_str);

    bool getReport(std::string& val) const;
    bool getPlayers(size_t index, std::string& val) const;
    bool getPlayersVector(std::vector<std::string>& val) const;

    void setReport(const std::string& val);
    void setPlayers(const std::vector<std::string>& val);

    void from_json(const std::string& json_str) override;
    std::string to_json() const override;
};


#endif // RESULT_SCHEMA_H
